#!/usr/bin/env bash
#
# A wizard walks a human through a manual procedure, step by step.
# Generated by the /wizard skill.
#
# Everything above the "STAGES" marker is the wizard library: do not hand-edit
# it. Author the per-step stages below the marker.

set -euo pipefail

# ──────────────────────────────────────────────────────────────────────────
# Wizard library: delightful, consistent UX, identical across every wizard.
# ──────────────────────────────────────────────────────────────────────────

if [[ -t 1 ]] && command -v tput >/dev/null 2>&1 && [[ "$(tput colors 2>/dev/null || echo 0)" -ge 8 ]]; then
  BOLD=$(tput bold); DIM=$(tput dim); RESET=$(tput sgr0)
  BLUE=$(tput setaf 4); GREEN=$(tput setaf 2); YELLOW=$(tput setaf 3)
else
  BOLD=""; DIM=""; RESET=""; BLUE=""; GREEN=""; YELLOW=""
fi

# Author sets this at the top of the stages section.
TOTAL_STAGES=0

_STAGE_INDEX=0
ENV_FILE="${ENV_FILE:-.env}"
WRITTEN_ENV=()    # KEYs written to ENV_FILE this run
WRITTEN_SECRET=() # secret NAMEs set this run
SKIPPED=()        # things we couldn't do (e.g. gh missing)

# _clear wipes the terminal so only the current step is on screen. No-op when
# output isn't a terminal, so piped logs stay readable.
_clear() {
  [[ -t 1 ]] || return 0
  if command -v tput >/dev/null 2>&1 && tput clear 2>/dev/null; then return 0; fi
  printf '\033[2J\033[3J\033[H'
}

# banner "Title" shows the opening frame: what this wizard does.
banner() {
  _clear
  printf '\n%s%s  %s%s\n' "$BOLD" "$BLUE" "$1" "$RESET"
  printf '%s  %s stages%s\n\n' "$DIM" "$TOTAL_STAGES" "$RESET"
  printf '%s  You drive the browser; this wizard tells you exactly what to do and\n' "$DIM"
  printf '  captures the values you copy back. Stop any time with Ctrl-C and re-run\n'
  printf '  later, since it remembers values already saved.%s\n' "$RESET"
  pause "Ready to start?"
}

# stage "Name" clears the screen, then announces a stage and shows progress.
# Clearing keeps only the current step on screen.
stage() {
  _clear
  _STAGE_INDEX=$((_STAGE_INDEX + 1))
  printf '\n%s%s▸ Stage %s/%s · %s%s\n' \
    "$BOLD" "$BLUE" "$_STAGE_INDEX" "$TOTAL_STAGES" "$1" "$RESET"
}

# say "..." prints a plain instruction line.
say()  { printf '  %s\n' "$1"; }
# step "..." is a numbered-feeling action the human takes in the browser.
step() { printf '  %s•%s %s\n' "$BLUE" "$RESET" "$1"; }
note() { printf '  %s%s%s\n' "$DIM" "$1" "$RESET"; }
warn() { printf '  %s⚠ %s%s\n' "$YELLOW" "$1" "$RESET"; }

# open_url URL opens it in the human's browser, cross-platform incl. WSL.
open_url() {
  local url="$1"
  printf '  %s↗ opening%s %s\n' "$GREEN" "$RESET" "$url"
  { if   command -v wslview     >/dev/null 2>&1; then wslview "$url"
    elif command -v explorer.exe >/dev/null 2>&1; then explorer.exe "$url"
    elif command -v xdg-open    >/dev/null 2>&1; then xdg-open "$url"
    elif command -v open        >/dev/null 2>&1; then open "$url"
    else false; fi
  } >/dev/null 2>&1 || warn "couldn't open a browser, so visit it manually: $url"
}

# pause "msg" waits for the human to confirm they've done the manual part.
pause() {
  printf '  %s%s%s ' "$DIM" "${1:-Press Enter to continue}" "$RESET"
  read -r _ || true
}

# confirm "question" is a y/N gate; returns success on yes.
confirm() {
  local reply=""
  printf '  %s? %s [y/N] ' "$YELLOW" "$1"
  read -r reply || true
  [[ "$reply" =~ ^[Yy] ]]
}

# _existing KEY: current value of KEY in ENV_FILE, if any, with write_env's single
# quotes or a plain dotenv double-quoted value undone.
_existing() {
  [[ -f "$ENV_FILE" ]] || return 1
  local line value sq="'\\''"; line=$(grep -E "^${1}=" "$ENV_FILE" | tail -n1) || return 1
  value="${line#*=}"
  if [[ "$value" == \'*\' ]]; then value="${value:1:${#value}-2}"; value="${value//"$sq"/\'}"
  elif [[ "$value" == \"*\" ]]; then
    value="${value:1:${#value}-2}"
    [[ "$value" == *[\\\$\"]* ]] && return 1   # escapes, $ or ": can't decode safely; ask again
  fi
  printf '%s' "$value"
}

# ask KEY "Prompt" reads a value into $KEY. Offers the existing .env value as
# a default on re-runs (Enter keeps it). Visible input (non-secret), edited
# with Readline. Fails at EOF with no input.
ask() {
  local key="$1" prompt="$2" current input s=$'\001' e=$'\002' p rc=0
  current=$(_existing "$key" || true)
  # Readline needs the colour codes wrapped in \001..\002 to place the cursor.
  p="  $s$BOLD$e$prompt$s$RESET$e "
  [[ -n "$current" ]] && p+="$s$DIM$e[Enter keeps current]$s$RESET$e "
  read -e -r -p "$p" input || rc=1
  if (( rc )) && [[ -z "$input" ]]; then return 1; fi
  [[ -z "$input" && -n "$current" ]] && input="$current"
  printf -v "$key" '%s' "$input"
}

# ask_secret KEY "Prompt" is like ask, but input is hidden.
ask_secret() {
  local key="$1" prompt="$2" current input rc=0
  current=$(_existing "$key" || true)
  if [[ -n "$current" ]]; then
    printf '  %s%s%s %s[Enter keeps current]%s ' "$BOLD" "$prompt" "$RESET" "$DIM" "$RESET"
  else
    printf '  %s%s%s ' "$BOLD" "$prompt" "$RESET"
  fi
  read -rs input || rc=1
  printf '\n'
  if (( rc )) && [[ -z "$input" ]]; then return 1; fi
  [[ -z "$input" && -n "$current" ]] && input="$current"
  printf -v "$key" '%s' "$input"
}

# write_env KEY VALUE upserts KEY='VALUE' into ENV_FILE (replaces any existing
# line) and sets $KEY. Idempotent. Creates ENV_FILE at mode 0600; writes through
# a symlink and keeps an existing file's mode.
write_env() {
  local key="$1" value="$2" tmp sq="'\\''"
  [[ -e "$ENV_FILE" ]] || (umask 077 && : > "$ENV_FILE")
  tmp=$(mktemp)
  grep -vE "^${key}=" "$ENV_FILE" > "$tmp" || true
  printf "%s='%s'\n" "$key" "${value//\'/$sq}" >> "$tmp"
  cat "$tmp" > "$ENV_FILE"
  rm -f "$tmp"
  printf -v "$key" '%s' "$value"
  WRITTEN_ENV+=("$key")
  printf '  %s✓ wrote%s %s → %s\n' "$GREEN" "$RESET" "$key" "$ENV_FILE"
}

# set_secret NAME VALUE sets a GitHub Actions repo secret via gh. Falls back
# to a warning (and records it) if gh is unavailable or unauthenticated.
set_secret() {
  local name="$1" value="$2"
  if command -v gh >/dev/null 2>&1 && gh auth status >/dev/null 2>&1; then
    if printf '%s' "$value" | gh secret set "$name" >/dev/null 2>&1; then
      WRITTEN_SECRET+=("$name")
      printf '  %s✓ set%s GitHub secret %s\n' "$GREEN" "$RESET" "$name"
      return
    fi
  fi
  SKIPPED+=("GitHub secret $name (set it manually: gh secret set $name)")
  warn "skipped GitHub secret $name: gh not ready; set it later"
}

# set_var NAME VALUE sets a GitHub Actions repo variable (non-secret).
set_var() {
  local name="$1" value="$2"
  if command -v gh >/dev/null 2>&1 && gh auth status >/dev/null 2>&1; then
    if gh variable set "$name" --body "$value" >/dev/null 2>&1; then
      printf '  %s✓ set%s GitHub variable %s\n' "$GREEN" "$RESET" "$name"
      return
    fi
  fi
  SKIPPED+=("GitHub variable $name")
  warn "skipped GitHub variable $name, gh not ready; set it later"
}

# finish clears, then shows a closing summary of everything configured.
finish() {
  _clear
  printf '\n%s%s  ✓ Setup complete%s\n' "$BOLD" "$GREEN" "$RESET"
  (( ${#WRITTEN_ENV[@]} ))    && note "wrote ${#WRITTEN_ENV[@]} value(s) to $ENV_FILE: ${WRITTEN_ENV[*]}"
  (( ${#WRITTEN_SECRET[@]} )) && note "set ${#WRITTEN_SECRET[@]} GitHub secret(s): ${WRITTEN_SECRET[*]}"
  if (( ${#SKIPPED[@]} )); then
    printf '\n'; warn "still to do by hand:"
    for s in "${SKIPPED[@]}"; do note "  - $s"; done
  fi
  printf '\n'
}

# ──────────────────────────────────────────────────────────────────────────
# STAGES: author this section. One stage() per step the human takes.
# Replace the example below. Set TOTAL_STAGES to match the stages you write.
# Keep every stage inside run_wizard and the last line as is: bash then parses
# the whole file before the first prompt, so an edit mid-run can't break it.
# ──────────────────────────────────────────────────────────────────────────

# ── Owner provisioning stages (#258) ──────────────────────────────────────
# Only things that need the owner's legal person, payment, accounts or signature.
# UI labels in third-party dashboards change: where a step says "labels may
# differ", follow the intent, not the exact words. Nothing here is verified
# against a live account.

DRY_RUN=0
REPO="${REPO:-jeffnawroth/source-taster}"
GH_ENV="scalingo-paris-verification"
OUTDIR_DEFAULT="$HOME/source-taster-owner-setup"

# put_env_secret NAME VALUE: environment secret on $GH_ENV (never the repo level).
put_env_secret() {
  local name="$1" value="$2"
  if (( DRY_RUN )); then
    note "dry-run: would set environment secret $name on $GH_ENV"; return
  fi
  if printf '%s' "$value" | gh secret set "$name" --env "$GH_ENV" --repo "$REPO" >/dev/null 2>&1; then
    WRITTEN_SECRET+=("$name"); printf '  %s✓ set%s environment secret %s\n' "$GREEN" "$RESET" "$name"
  else
    SKIPPED+=("environment secret $name: gh secret set $name --env $GH_ENV --repo $REPO")
    warn "skipped environment secret $name"
  fi
}

# put_env_var NAME VALUE: environment variable on $GH_ENV.
put_env_var() {
  local name="$1" value="$2"
  if (( DRY_RUN )); then
    note "dry-run: would set environment variable $name on $GH_ENV"; return
  fi
  if gh variable set "$name" --body "$value" --env "$GH_ENV" --repo "$REPO" >/dev/null 2>&1; then
    printf '  %s✓ set%s environment variable %s\n' "$GREEN" "$RESET" "$name"
  else
    SKIPPED+=("environment variable $name: gh variable set $name --env $GH_ENV --repo $REPO")
    warn "skipped environment variable $name"
  fi
}

run_wizard() {

local arg
for arg in "$@"; do
  case "$arg" in
    --dry-run) DRY_RUN=1 ;;
    -h|--help)
      printf 'Usage: scripts/owner-setup.sh [--dry-run]\n'
      printf '  --dry-run  write nothing to GitHub, generate no real keys, use a temporary output folder\n'
      printf '  REPO=owner/name overrides the GitHub repository (default %s)\n' "$REPO"
      return 0 ;;
    *) printf 'unknown option: %s\n' "$arg" >&2; return 2 ;;
  esac
done

local OUTDIR="$OUTDIR_DEFAULT"
if (( DRY_RUN )); then OUTDIR=$(mktemp -d); fi
(umask 077 && mkdir -p "$OUTDIR")
ENV_FILE="$OUTDIR/owner-values.env"

TOTAL_STAGES=13

banner "Source Taster: owner provisioning"

# ── 1 Preflight ───────────────────────────────────────────────────────────
stage "Preflight"
say "This wizard covers what only the owner can do: accounts, payment, identity,"
say "signing keys. It never deploys, never contacts a provider for you, and never"
say "commits anything. Values go to $OUTDIR (mode 0700, outside the repository)."
(( DRY_RUN )) && warn "DRY RUN: nothing is written to GitHub, no real keys are generated."
local missing=()
command -v node >/dev/null 2>&1 || missing+=(node)
command -v curl >/dev/null 2>&1 || missing+=(curl)
command -v shasum >/dev/null 2>&1 || command -v sha256sum >/dev/null 2>&1 || missing+=(shasum)
if (( ${#missing[@]} )); then warn "missing tools: ${missing[*]}"; return 1; fi
if command -v gh >/dev/null 2>&1 && gh auth status >/dev/null 2>&1; then
  say "GitHub CLI is signed in."
else
  SKIPPED+=("GitHub steps: run gh auth login, then re-run this wizard")
  warn "gh is missing or not signed in: GitHub writes will be skipped and listed at the end."
fi
note "Repository: $REPO   Environment: $GH_ENV"
pause "Continue?"

# ── 2 Domain ──────────────────────────────────────────────────────────────
stage "Domain and registrar"
say "You need one domain for the website, the web app, the API and e-mail."
step "Pick a registrar in an EU country and register the domain in your own name."
step "Turn on registrar two-factor sign-in and registrar lock."
ask DOMAIN "Registered domain (for example example.org):"
write_env DOMAIN "$DOMAIN"
note "Domain, support address and seller fields in apps/website/publication.json stay null until the legal review (#257) is approved."

# ── 3 Mailbox ─────────────────────────────────────────────────────────────
stage "Support mailbox"
say "The legal notice needs a fast electronic contact. Create a real mailbox."
step "Create the mailbox, for example support@$DOMAIN, at your mail host."
step "Send yourself a test message and reply to it."
ask SUPPORT_ADDRESS "Support address:"
write_env SUPPORT_ADDRESS "$SUPPORT_ADDRESS"

# ── 4 Seller identity ─────────────────────────────────────────────────────
stage "Seller identity (stays in your private values file)"
say "The legal notice and every invoice need the legal person that sells."
say "Type the values exactly as they appear in your register entry or tax papers."
ask SELLER_NAME "Seller name:"
ask SELLER_ADDRESS "Postal address (street, postcode, city):"
ask SELLER_COUNTRY "Country:"
ask SELLER_LEGAL "Register court and number, VAT ID (one line, or 'none'):"
write_env SELLER_NAME "$SELLER_NAME"
write_env SELLER_ADDRESS "$SELLER_ADDRESS"
write_env SELLER_COUNTRY "$SELLER_COUNTRY"
write_env SELLER_LEGAL "$SELLER_LEGAL"
note "These fill apps/website/publication.json (seller.name, address, country, legalDetails). A human commits them after the legal review; this wizard does not."

# ── 5 Scalingo ────────────────────────────────────────────────────────────
stage "Scalingo: account, Paris app, deploy token"
open_url "https://dashboard.scalingo.com/"
step "Create or sign in to the account. Turn on two-factor sign-in."
step "Create a new app in region osc-fr1 (Paris) for the verification program."
step "Open the app, then Settings or Info. Copy the app ID (a UUID). Labels may differ."
ask SCALINGO_APP_ID "App ID (UUID):"
if [[ ! "$SCALINGO_APP_ID" =~ ^[a-f0-9-]{36}$ ]]; then
  warn "That does not look like a lowercase UUID (36 characters). The deployment check refuses anything else."
fi
write_env SCALINGO_APP_ID "$SCALINGO_APP_ID"
open_url "https://dashboard.scalingo.com/account/tokens"
step "Create an API token named source-taster-deploy. Copy it once; it is shown only once."
ask_secret SCALINGO_API_TOKEN "Paste the token (hidden):"
write_env SCALINGO_API_TOKEN "$SCALINGO_API_TOKEN"
say "The PostgreSQL 18 add-on and the isolation settings are set up from the"
say "deployment note docs/implementation/116-deployment-backup-status.md, not here."

# ── 6 Scalingo CLI pin ────────────────────────────────────────────────────
stage "Scalingo CLI: pinned download and hash"
say "The deploy workflow downloads one exact CLI archive and checks its hash."
open_url "https://github.com/Scalingo/cli/releases"
step "Choose a release. Copy the link of the linux amd64 .tar.gz asset."
ask SCALINGO_CLI_URL "Asset URL (https://github.com/Scalingo/cli/releases/download/...):"
if [[ "$SCALINGO_CLI_URL" != https://github.com/Scalingo/cli/releases/download/* ]]; then
  warn "The workflow refuses any other prefix."
  return 1
fi
local cli_tmp; cli_tmp=$(mktemp)
if curl --fail --silent --show-error --location "$SCALINGO_CLI_URL" -o "$cli_tmp"; then
  if command -v sha256sum >/dev/null 2>&1; then SCALINGO_CLI_SHA256=$(sha256sum "$cli_tmp" | cut -d' ' -f1)
  else SCALINGO_CLI_SHA256=$(shasum -a 256 "$cli_tmp" | cut -d' ' -f1); fi
  say "SHA-256 of the download: $SCALINGO_CLI_SHA256"
  warn "This hash is of what your machine just received. Compare it with the checksum"
  warn "file published on the same release page before you trust it."
  confirm "Does it match the published checksum?" || { rm -f "$cli_tmp"; warn "Stopped: do not pin an unchecked archive."; return 1; }
else
  rm -f "$cli_tmp"; warn "download failed"; return 1
fi
rm -f "$cli_tmp"
write_env SCALINGO_CLI_URL "$SCALINGO_CLI_URL"
write_env SCALINGO_CLI_SHA256 "$SCALINGO_CLI_SHA256"

# ── 7 Scaleway ────────────────────────────────────────────────────────────
stage "Scaleway: bucket with Object Lock, access keys"
open_url "https://console.scaleway.com/"
step "Create or sign in to the account. Turn on two-factor sign-in. Create a project."
step "Object Storage > Create bucket. Region Paris (fr-par)."
step "Enable versioning and Object Lock at creation. It cannot be added later. Labels may differ."
step "Do not set a bucket-wide default retention; each upload sets 312 hours COMPLIANCE."
ask BACKUP_BUCKET "Bucket name:"
write_env BACKUP_BUCKET "$BACKUP_BUCKET"
open_url "https://console.scaleway.com/iam/api-keys"
step "IAM > Applications: create an application for backups and give it only object write and read on this project."
step "API keys: generate a key for that application. Copy both values."
ask BACKUP_ACCESS_KEY "Access key:"
ask_secret BACKUP_SECRET_KEY "Secret key (hidden):"
write_env BACKUP_ACCESS_KEY "$BACKUP_ACCESS_KEY"
write_env BACKUP_SECRET_KEY "$BACKUP_SECRET_KEY"
note "These go to the backup job's private configuration (OPS_CONFIG), never to GitHub."

# ── 8 Scaleway mail ───────────────────────────────────────────────────────
stage "Scaleway Transactional Email: sending domain"
open_url "https://console.scaleway.com/transactional-email/domains"
step "Add the domain $DOMAIN. Choose the Essential plan."
step "At your DNS host, add the records the console shows: SPF, DKIM, and a DMARC record."
step "Wait until the console shows the domain as verified. Labels may differ."
step "Create SMTP credentials for the service. Copy them."
ask SMTP_USER "SMTP username:"
ask_secret SMTP_PASSWORD "SMTP password (hidden):"
write_env SMTP_USER "$SMTP_USER"
write_env SMTP_PASSWORD "$SMTP_PASSWORD"
note "SMTP belongs to the private service. Put it in the password manager; the wizard keeps it only in the values file."

# ── 9 Signing keys ────────────────────────────────────────────────────────
stage "Offline keys: deployment approval and backup"
say "Two key pairs, generated here with Node's own crypto:"
say " - Ed25519 approval key: signs each release's approval packet."
say " - RSA-3072 backup key: only its PUBLIC half goes to the server."
say "Private halves are written once, mode 0600, and never to GitHub."
local KEYDIR="$OUTDIR/offline-keys"
(umask 077 && mkdir -p "$KEYDIR")
if (( DRY_RUN )); then
  note "dry-run: keys not generated"
  DEPLOY_APPROVAL_PUBLIC_KEY="-----BEGIN PUBLIC KEY-----(dry-run)-----END PUBLIC KEY-----"
elif [[ -e "$KEYDIR/approval-private.pem" || -e "$KEYDIR/backup-private.pem" ]]; then
  warn "Keys already exist in $KEYDIR. Not overwriting them."
  DEPLOY_APPROVAL_PUBLIC_KEY=$(cat "$KEYDIR/approval-public.pem")
else
  KEYDIR="$KEYDIR" node --input-type=module -e '
    import { generateKeyPairSync } from "node:crypto";
    import { writeFileSync } from "node:fs";
    const d = process.env.KEYDIR;
    const out = (name, k) => writeFileSync(`${d}/${name}`, k, { mode: 0o600, flag: "wx" });
    const a = generateKeyPairSync("ed25519");
    out("approval-private.pem", a.privateKey.export({ type: "pkcs8", format: "pem" }));
    out("approval-public.pem", a.publicKey.export({ type: "spki", format: "pem" }));
    const b = generateKeyPairSync("rsa", { modulusLength: 3072 });
    out("backup-private.pem", b.privateKey.export({ type: "pkcs8", format: "pem" }));
    out("backup-public.pem", b.publicKey.export({ type: "spki", format: "pem" }));
  '
  DEPLOY_APPROVAL_PUBLIC_KEY=$(cat "$KEYDIR/approval-public.pem")
  say "Wrote four files to $KEYDIR."
fi
cat > "$OUTDIR/sign-approval.mjs" <<'SIGN'
// Usage: node sign-approval.mjs approval-private.pem approval.json > approval.sig
import { readFileSync } from "node:fs";
import { sign } from "node:crypto";
const [keyFile, packetFile] = process.argv.slice(2);
process.stdout.write(sign(null, readFileSync(packetFile), readFileSync(keyFile)).toString("base64"));
SIGN
note "Helper written: $OUTDIR/sign-approval.mjs (signs an approval packet; output is base64, as the deploy check expects)."
warn "Move approval-private.pem and backup-private.pem to an encrypted offline medium NOW."
warn "Without backup-private.pem the exports cannot be restored. Keep a second copy in a different place."
confirm "Both private keys are stored offline and I have a second copy?" || SKIPPED+=("store the offline private keys and a second copy, then delete them from $KEYDIR")
note "The server needs only backup-public.pem (path set in deploy/backup.example.json as publicKey)."

# ── 10 GitHub environment ─────────────────────────────────────────────────
stage "GitHub: protected environment, secrets and variables"
say "The deploy workflow runs in the environment $GH_ENV. It needs required"
say "reviewers so that a deploy pauses for a human."
if (( DRY_RUN )); then
  note "dry-run: would create environment $GH_ENV with you as required reviewer"
elif command -v gh >/dev/null 2>&1 && gh auth status >/dev/null 2>&1; then
  local uid; uid=$(gh api user --jq .id 2>/dev/null || true)
  if [[ "$uid" =~ ^[0-9]+$ ]] && printf '{"prevent_self_review":false,"reviewers":[{"type":"User","id":%s}]}' "$uid" \
      | gh api -X PUT "repos/$REPO/environments/$GH_ENV" --input - >/dev/null 2>&1; then
    say "Environment $GH_ENV exists with you as required reviewer."
  else
    SKIPPED+=("create environment $GH_ENV with required reviewers: repository Settings > Environments")
    warn "Could not create the environment through the API."
  fi
else
  SKIPPED+=("create environment $GH_ENV with required reviewers: repository Settings > Environments")
fi
put_env_secret SCALINGO_API_TOKEN "$SCALINGO_API_TOKEN"
put_env_var SCALINGO_CLI_URL "$SCALINGO_CLI_URL"
put_env_var SCALINGO_CLI_SHA256 "$SCALINGO_CLI_SHA256"
put_env_var DEPLOY_APPROVAL_PUBLIC_KEY "$DEPLOY_APPROVAL_PUBLIC_KEY"
say "The workflow also reads a private qualification repository:"
ask QUALIFICATION_REPOSITORY "Repository that holds the qualification inputs (owner/name):"
ask QUALIFICATION_COMMIT "Exact 40-character commit to pin:"
if [[ ! "$QUALIFICATION_COMMIT" =~ ^[a-f0-9]{40}$ ]]; then warn "Not a 40-character lowercase hex commit: the workflow refuses it."; fi
write_env QUALIFICATION_REPOSITORY "$QUALIFICATION_REPOSITORY"
write_env QUALIFICATION_COMMIT "$QUALIFICATION_COMMIT"
put_env_var QUALIFICATION_REPOSITORY "$QUALIFICATION_REPOSITORY"
put_env_var QUALIFICATION_COMMIT "$QUALIFICATION_COMMIT"
open_url "https://github.com/settings/personal-access-tokens/new"
step "Create a fine-grained token: resource owner = your account, only that private repository, permission Contents: read-only, shortest practical expiry."
ask_secret QUALIFICATION_READ_TOKEN "Paste the token (hidden):"
write_env QUALIFICATION_READ_TOKEN "$QUALIFICATION_READ_TOKEN"
put_env_secret QUALIFICATION_READ_TOKEN "$QUALIFICATION_READ_TOKEN"
note "Not set here, they come from each release: DEPLOY_CONFIGURATION_JSON, DEPLOY_APPROVAL_JSON, DEPLOY_APPROVAL_SIGNATURE, MEASURED_CONFIGURATIONS_JSON (secrets); QUALITY_EXTRACTION, QUALITY_CONFIGURATION_FILE, QUALITY_ROOT, LOAD_REPORT (variables)."

# ── 11 Stripe ─────────────────────────────────────────────────────────────
stage "Stripe: payment account"
open_url "https://dashboard.stripe.com/register"
step "Register the account for the seller legal person from stage 4."
step "Complete business verification: this needs your identity papers and bank account."
step "Turn on two-factor sign-in. Keep the account in test mode until the legal review is done."
open_url "https://dashboard.stripe.com/test/apikeys"
step "Copy the test secret key (starts sk_test_)."
ask_secret STRIPE_TEST_SECRET_KEY "Paste the test secret key (hidden):"
write_env STRIPE_TEST_SECRET_KEY "$STRIPE_TEST_SECRET_KEY"
note "Stripe belongs to the private purchase service. Keep it in the password manager. Mollie is the fallback in ADR-0009; nothing to set up unless Stripe declines the account."

# ── 12 Status monitor ─────────────────────────────────────────────────────
stage "Better Stack: heartbeat and status page"
open_url "https://betterstack.com/"
step "Create the account. Turn on two-factor sign-in."
step "Create a heartbeat monitor. Copy its URL (https://uptime.betterstack.com/api/v1/heartbeat/...)."
ask HEARTBEAT_URL "Heartbeat URL:"
write_env HEARTBEAT_URL "$HEARTBEAT_URL"
step "Create a status page and attach it to a status subdomain of $DOMAIN."
note "The URL goes into the private OPS_STATUS_CONFIG (see deploy/status.example.json)."

# ── 13 Browser stores ─────────────────────────────────────────────────────
stage "Browser extension developer accounts"
say "Registering needs your identity and, for Chrome, a one-time fee. Listing text and"
say "screenshots are a separate task (#259); this stage only creates the accounts."
open_url "https://chrome.google.com/webstore/devconsole"
confirm "Chrome Web Store developer account is registered?" || SKIPPED+=("Chrome Web Store developer account")
open_url "https://partner.microsoft.com/dashboard/microsoftedge/overview"
confirm "Microsoft Edge Add-ons developer account is registered?" || SKIPPED+=("Microsoft Edge Add-ons developer account")
open_url "https://addons.mozilla.org/developers/"
confirm "Firefox (AMO) developer account is registered?" || SKIPPED+=("Firefox AMO developer account")
(( DRY_RUN )) && note "dry-run output folder: $OUTDIR (temporary, safe to delete)"
say ""
say "Stored privately in $OUTDIR:"
say " - owner-values.env (all captured values, mode 0600)"
say " - offline-keys/ (move the private halves offline, then delete them here)"
say " - sign-approval.mjs"
say "Still ahead of launch (human): lawyer review (#257), contracts and the DPA,"
say "the withdrawal-function decision (change request C05), and the first release approval."

finish
}

run_wizard "$@"; exit
